import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

// Load font at module level to guarantee availability before frame 0
const { fontFamily } = loadMontserrat();



export type WindingTimeProps = Record<string, any>;

const WindingTime: React.FC<WindingTimeProps> = ({
  backgroundColor = "#0B1226",
  transparentBackground = false,
  durationInSeconds = 8,
  titleLine1 = "WINDING",
  titleLine2 = "BACK TIME",
  targetAmount = 80,
  unitText = "HOURS",
  gradientStart = "#48E3FF",
  gradientEnd = "#1F83FF",
  textColor = "#FFFFFF",
  clockFaceColor = "#F4F6FB",
  clockDarkColor = "#0B1A35",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  // Background transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Animation Timings ---
  // Entrance scaling
  const faceScale = spring({ frame: frame - 5, fps, config: { damping: 14, mass: 0.8 } });
  const arrowScale = spring({ frame: frame - 15, fps, config: { damping: 14, mass: 0.8 } });
  
  // Text stagger entrance
  const title1Y = interpolate(frame, [15, 35], [50, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp", easing: Easing.out(Easing.cubic) });
  const title1Op = interpolate(frame, [15, 35], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  const title2Y = interpolate(frame, [25, 45], [50, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp", easing: Easing.out(Easing.cubic) });
  const title2Op = interpolate(frame, [25, 45], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  const badgeScale = spring({ frame: frame - 40, fps, config: { damping: 12, mass: 0.9 } });
  const badgeOp = interpolate(frame, [40, 50], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  // Counter & Clock Spin (Counts from 0 to targetAmount between frame 50 and 120)
  const countProgress = interpolate(frame, [50, 120], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
    easing: Easing.inOut(Easing.cubic),
  });
  
  const displayedAmount = Math.round(countProgress * targetAmount);
  
  // Winding back time mapping (negative rotation for CCW)
  const hourHandRot = -countProgress * targetAmount * 30; // 30 degrees per hour
  const minuteHandRot = -countProgress * targetAmount * 360; // 360 degrees per hour

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily, display: "flex", flexDirection: "row", alignItems: "center", justifyContent: "center" }}>
      <div style={{ display: "flex", gap: `${100 * s}px`, alignItems: "center", width: "100%", justifyContent: "center" }}>
        
        {/* Left: Clock Icon */}
        <div style={{ width: `${500 * s}px`, height: `${500 * s}px`, position: "relative", flexShrink: 0 }}>
          <svg viewBox="-65 -65 130 130" width="100%" height="100%" style={{ overflow: "visible" }}>
            <defs>
              {/* Gradient for the winding arrow (Bottom to Top) */}
              <linearGradient id="arrowGrad" x1="100%" y1="100%" x2="0%" y2="0%">
                <stop offset="0%" stopColor={gradientEnd} />
                <stop offset="100%" stopColor={gradientStart} />
              </linearGradient>
            </defs>

            {/* Inner Clock Face */}
            <g transform={`scale(${faceScale})`} style={{ transition: "none" }}>
              <circle cx="0" cy="0" r="36" fill={clockFaceColor} />
              
              {/* Clock Ticks */}
              {[0, 90, 180, 270].map((deg) => (
                <line key={deg} x1="0" y1="-28" x2="0" y2="-20" stroke={clockDarkColor} strokeWidth="3" strokeLinecap="round" transform={`rotate(${deg})`} />
              ))}
              
              {/* Hands */}
              <line x1="0" y1="0" x2="0" y2="-16" stroke={clockDarkColor} strokeWidth="5" strokeLinecap="round" transform={`rotate(${hourHandRot})`} style={{ transition: "none" }} />
              <line x1="0" y1="0" x2="0" y2="-24" stroke={clockDarkColor} strokeWidth="4" strokeLinecap="round" transform={`rotate(${minuteHandRot})`} style={{ transition: "none" }} />
              
              {/* Center Dot */}
              <circle cx="0" cy="0" r="4.5" fill={clockDarkColor} />
            </g>

            {/* Outer Winding Arrow */}
            <g transform={`scale(${arrowScale})`} style={{ transition: "none" }}>
              {/* 
                Math for perfect arc: 
                R = 50. 
                Start at Bottom-Left (144 deg): x = -40.45, y = 29.39 
                End at Top-Left (-144 deg): x = -40.45, y = -29.39
                Sweep flag = 0 (CCW)
              */}
              <path 
                d="M -40.45 29.39 A 50 50 0 1 0 -40.45 -29.39" 
                fill="none" 
                stroke="url(#arrowGrad)" 
                strokeWidth="11" 
                strokeLinecap="round" 
              />
              {/* 
                Arrowhead placed at the exact end of the arc.
                Tangent angle at -144 deg CCW is -234 deg.
              */}
              <polygon 
                points="18,0 -8,-14 -8,14" 
                fill="url(#arrowGrad)" 
                transform="translate(-40.45, -29.39) rotate(-234)" 
              />
            </g>
          </svg>
        </div>

        {/* Right: Text Block */}
        <div style={{ display: "flex", flexDirection: "column", gap: `${15 * s}px`, flexShrink: 0 }}>
          
          <div style={{ 
            fontSize: `${140 * s}px`, 
            fontWeight: 900, 
            color: textColor, 
            lineHeight: 1, 
            transform: `translateY(${title1Y}px)`, 
            opacity: title1Op, 
            letterSpacing: "-0.01em",
            transition: "none"
          }}>
            {titleLine1}
          </div>
          
          <div style={{ 
            fontSize: `${140 * s}px`, 
            fontWeight: 900, 
            color: textColor, 
            lineHeight: 1, 
            transform: `translateY(${title2Y}px)`, 
            opacity: title2Op, 
            letterSpacing: "-0.01em",
            transition: "none"
          }}>
            {titleLine2}
          </div>

          {/* Badge */}
          <div style={{
            marginTop: `${20 * s}px`,
            background: `linear-gradient(90deg, ${gradientStart}, ${gradientEnd})`,
            borderRadius: `${30 * s}px`,
            padding: `${20 * s}px ${50 * s}px`,
            display: "flex", 
            alignItems: "baseline", 
            gap: `${30 * s}px`,
            transform: `scale(${badgeScale})`, 
            opacity: badgeOp, 
            transformOrigin: "left center",
            alignSelf: "flex-start",
            boxShadow: `0 ${15 * s}px ${40 * s}px rgba(0,0,0,0.25)`,
            transition: "none"
          }}>
            <div style={{ 
              fontSize: `${170 * s}px`, 
              fontWeight: 900, 
              color: clockDarkColor, 
              lineHeight: 1, 
              letterSpacing: "-0.03em",
              fontVariantNumeric: "tabular-nums"
            }}>
              {displayedAmount.toLocaleString()}
            </div>
            <div style={{ 
              fontSize: `${75 * s}px`, 
              fontWeight: 800, 
              color: clockDarkColor, 
              lineHeight: 1, 
              letterSpacing: "0.02em" 
            }}>
              {unitText}
            </div>
          </div>
          
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default WindingTime;